lot_id = movement["lot_id"].strip()
source = movement["from_location"].strip()
destination = movement["to_location"].strip()
if source == destination:
    raise ValueError("source and destination must be different locations")

try:
    quantity = Decimal(str(movement["quantity"]))
    available = Decimal(str(stock.get(source, {}).get(lot_id, 0)))
    destination_balance = Decimal(str(stock.get(destination, {}).get(lot_id, 0)))
except (InvalidOperation, TypeError, ValueError) as exc:
    raise ValueError("stock and movement quantities must be valid decimals") from exc

if not quantity.is_finite() or quantity <= 0:
    raise ValueError("transfer quantity must be greater than zero")
if not available.is_finite() or available < quantity:
    raise ValueError("insufficient source stock for this transfer")
if not destination_balance.is_finite() or destination_balance < 0:
    raise ValueError("destination stock balance must be non-negative")

updated = {location: dict(lots) for location, lots in stock.items()}
source_lots = updated.setdefault(source, {})
remaining = available - quantity
if remaining == 0:
    source_lots.pop(lot_id, None)
else:
    source_lots[lot_id] = remaining

destination_lots = updated.setdefault(destination, {})
destination_lots[lot_id] = destination_balance + quantity

